/**
 * Pronunciation for the whole app. Uses the learner's choice: the browser's voices (free) or a
 * cloud voice generated by the server with their own API key (cached there). If a cloud voice
 * fails, it falls back to the browser so the learner always hears something.
 */
import type { TtsProvider } from '@alivocab/shared';
import { toast } from 'sonner';
import { reportProblem } from './activity.ts';
import { api, errorMessage, unwrap } from './api.ts';

/** The provider is shared; each learning language has its own voice (PLAN.md D31). */
type SpeechConfig = { provider: TtsProvider; voices: Record<string, string | null> };

let config: SpeechConfig = { provider: 'browser', voices: {} };
/** Cloud audio URLs by text/language/voice, so repeats don't ask the server again. */
const urls = new Map<string, Promise<string>>();
let audio: HTMLAudioElement | null = null;
let warned = false;

const browserSupported = () => typeof window !== 'undefined' && 'speechSynthesis' in window;

export function configureSpeech(next: SpeechConfig) {
  config = next;
}

export const speechProvider = () => config.provider;

export function stopSpeaking() {
  audio?.pause();
  audio = null;
  if (browserSupported()) window.speechSynthesis.cancel();
}

function browserSpeak(text: string, lang: string, voiceURI: string | null, rate: number) {
  return new Promise<void>((resolve) => {
    if (!browserSupported()) return resolve();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = lang;
    utterance.rate = rate;
    const voice = window.speechSynthesis.getVoices().find((v) => v.voiceURI === voiceURI);
    if (voice) utterance.voice = voice;
    utterance.onend = () => resolve();
    utterance.onerror = () => resolve();
    window.speechSynthesis.speak(utterance);
  });
}

function cloudUrl(text: string, lang: string, voice: string | null): Promise<string> {
  const key = `${config.provider}\u0000${voice ?? ''}\u0000${lang}\u0000${text}`;
  let url = urls.get(key);
  if (!url) {
    url = unwrap(api.tts.$post({ json: { text, lang, ...(voice ? { voice } : {}) } })).then(
      (r) => r.url,
    );
    url.catch(() => urls.delete(key));
    urls.set(key, url);
  }
  return url;
}

/**
 * Speaks `text` with the learner's voice for `lang`; resolves when it has finished. `voice`
 * overrides it (e.g. the second speaker in a dialogue); `rate` is the playback speed (1 = normal).
 */
export async function speak(
  text: string,
  lang: string,
  { voice, rate = 1 }: { voice?: string | null; rate?: number } = {},
): Promise<void> {
  stopSpeaking();
  const chosen = voice ?? config.voices[lang] ?? null;
  if (config.provider === 'browser') {
    return browserSpeak(text, lang, chosen, rate);
  }
  try {
    const url = await cloudUrl(text, lang, chosen);
    const player = new Audio(url);
    audio = player;
    player.playbackRate = rate;
    await new Promise<void>((resolve, reject) => {
      player.onended = () => resolve();
      player.onpause = () => resolve();
      player.onerror = () => reject(new Error('Could not play the audio'));
      player.play().catch(reject);
    });
  } catch (err) {
    reportProblem(`Cloud voice failed: ${errorMessage(err)}`, {
      level: 'warn',
      context: 'pronunciation',
      details: { provider: config.provider, lang, text: text.slice(0, 80) },
    });
    if (!warned) {
      warned = true;
      toast.error(`Cloud voice unavailable (${errorMessage(err)}). Using the browser’s voice.`);
    }
    return browserSpeak(text, lang, null, rate);
  }
}
